messages.content:
Tool response:
Tool: compare_stock_availability
Description: Compare Stock Availability
Parameters:
    {
      "type": "object",
      "properties": {
        "part_sku": {
          "type": "string",
          "description": "SKU of the aftermarket part to compare",
          "title": "Part Sku"
        },
        "warehouse_code_1": {
          "type": "string",
          "description": "Code of the first warehouse (e.g., WH-DAL)",
          "title": "Warehouse Code 1"
        },
        "warehouse_code_2": {
          "type": "string",
          "description": "Code of the second warehouse (e.g., WH-ATL)",
          "title": "Warehouse Code 2"
        }
      },
      "required": [
        "part_sku",
        "warehouse_code_1",
        "warehouse_code_2"
      ]
    }
